const req = $input.first().json.body || $input.first().json;

const monthly = Number(req.monthlyInvestment || 5000);
const annualReturn = Number(req.annualReturn || 12);
const years = Number(req.years || 10);
const stepUpPct = Number(req.stepUpPercentage || 0) / 100;

const r = annualReturn / 100 / 12;
const months = years * 12;

let totalInvested = 0;
let estimatedValue = 0;
let currentMonthly = monthly;

for (let m = 1; m <= months; m++) {
  if (m > 1 && (m - 1) % 12 === 0 && stepUpPct > 0) {
    currentMonthly = currentMonthly * (1 + stepUpPct);
  }
  totalInvested += currentMonthly;
  estimatedValue = (estimatedValue + currentMonthly) * (1 + r);
}

totalInvested = Math.round(totalInvested);
estimatedValue = Math.round(estimatedValue);
const estimatedGain = estimatedValue - totalInvested;

return {
  json: {
    success: true,
    intent: 'WEALTH',
    subIntent: 'SIP_CALCULATOR',
    label: 'Illustrative scenario — not guaranteed.',
    data: {
      monthlyInvestment: monthly,
      annualReturn,
      years,
      stepUpPercentage: req.stepUpPercentage || 0,
      totalInvested,
      estimatedGain,
      estimatedValue
    },
    timestamp: new Date().toISOString()
  }
};
